window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"Słowo *als* ma kilka znaczeń. Napisz zdanie do każdego znaczenia.","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"Trzy znaczenia: *als* = kiedy, gdy (jedno zdarzenie w przeszłości, czasownik na końcu zdania), *als* po stopniu wyższym = niż, *als* + zawód lub rola = jako. Dla czegoś, co w przeszłości działo się wiele razy, użyj *wenn*, nie *als*."}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"Napisz krótkie opowiadanie ze słowami z tej lekcji.","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"Przykładowa odpowiedź; twoja może być zupełnie inna. Po polsku: „… że udało mi się zrobić sobie z nim zdjęcie. Co prawda zabrakło mi odwagi, żeby z nim porozmawiać, ale potem przyszła wielka niespodzianka: zapytał mnie, gdzie jest dworzec!” Tekst wykorzystuje *zwar … aber*, *der Mut* i *die Überraschung* z lekcji 1."}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"Ucz się typowych zwrotów w całości.","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* uzupełnia listę z książki (zbadać brzuch). Pozostałe to pary słów z tej lekcji, których warto uczyć się jako jednej całości: zaszczepić się, przepisać lek, wystawić komuś zwolnienie lekarskie, prowadzić rozmowę, umówić się na wizytę, uprawiać sport, zrezygnować z czekolady."}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"Po niemiecku nazwy wielu języków kończą się na -isch. Napisz kilka.","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"Nazwy języków są rodzaju nijakiego i zwykle nie mają rodzajnika: *Ich lerne Spanisch.* Nie każdy język kończy się na *-isch*: *Deutsch*, *Hindi* i *Swahili* nie."}],"count":60},{"batch":5,"added":"2026-11-09","lesson":5,"lesson_title":"Eine Arbeit finden","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 188–191","tips":[{"text":"Notieren Sie einen Beruf. Bilden Sie mit seinen Buchstaben einen Satz.","text_en":"Zapisz nazwę zawodu. Ułóż zdanie z jej liter.","example":"Maler: *M*ein *A*rzt *l*iest *e*inen *R*eiseführer.","answer":["Arzt: Anna ruft zwei Taxis","Lehrer: Lara erklärt heute Ronja einen Roman"],"note":"Każde słowo zaczyna się od kolejnej litery nazwy zawodu. Każde zdanie, które działa, jest dobre."}],"count":53},{"batch":6,"added":"2026-11-09","lesson":6,"lesson_title":"Dienstleistung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 191–195","tips":[{"text":"Bilden Sie mit den Buchstaben von einem langen Wort neue Wörter.","text_en":"Ułóż nowe słowa z liter jednego długiego słowa.","example":"Bedienungsanleitung: laut, Dienstag, Tal, …","answer":["Bad","Geld","Insel","Nadel","Lied","Sieg","Tanne","Leben"],"note":"Użyj każdej litery z *Bedienungsanleitung* najwyżej tyle razy, ile razy występuje w tym słowie."}],"count":66},{"batch":7,"added":"2026-11-09","lesson":7,"lesson_title":"Rund ums Wohnen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 196–200","tips":[{"text":"Leiten Sie unbekannte Wörter von bekannten Wörtern ab.","text_en":"Odgaduj znaczenie nieznanych słów na podstawie słów, które znasz.","example":"unaufmerksam = nicht aufmerksam","answer":["unverständlich = nicht verständlich","ungemütlich = nicht gemütlich","friedlich = ohne Streit, voller Frieden","der Stadtrand = der Rand der Stadt","das Fernsehverbot = das Verbot, fernzusehen"],"note":"*un-* zmienia przymiotnik w jego przeciwieństwo; rzeczownik złożony wyjaśnia jego ostatnia część."}],"count":67}];
